//
// _authentication.scss
//


.auth-page-wrapper{
    min-height: 100vh;
    min-height: 100dvh;
    position: relative;
    padding-top: 0 !important;
    overflow-x: hidden;
    background-color: transparent;

    #auth-particles.auth-one-bg-position,
    .auth-one-bg-position.auth-one-bg {
        position: relative;
        display: flex;
        flex-direction: column;
        min-height: 100vh;
        min-height: 100dvh;
        width: 100%;
    }

    .auth-page-content{
        flex: 1 0 auto;
        display: flex;
        flex-direction: column;
        justify-content: center;
        margin-top: 0 !important;
        padding-top: 1.5rem;
        padding-bottom: calc(#{$footer-height} + 1rem);
        position: relative;
        z-index: 2;
        width: 100%;

        .auth-signin-card {
            --#{$prefix}card-bg: #ffffff;
            background-color: #ffffff !important;
            border-color: var(--#{$prefix}border-color);

            .card-body {
                background-color: #ffffff !important;
            }

            .auth-signin-logo {
                display: block;
                margin-left: auto;
                margin-right: auto;
                width: auto;
                max-width: 100%;
                object-fit: contain;
            }
        }

        .auth-signin-btn {
            background-color: #1e88e5 !important;
            border-color: #1e88e5 !important;
            color: #ffffff !important;
            border-radius: var(--#{$prefix}border-radius) !important;
            box-shadow: none !important;

            &:hover,
            &:focus,
            &:active,
            &:disabled {
                background-color: #1976d2 !important;
                border-color: #1976d2 !important;
                color: #ffffff !important;
                box-shadow: none !important;
            }
        }
    }
    .footer{
        position: absolute;
        bottom: 0;
        left: 0 !important;
        right: 0;
        z-index: 2;
        background-color: transparent;
        color: #ffffff !important;

        p,
        .text-muted {
            color: #ffffff !important;
        }
    }
}

.auth-one-bg{
    position: relative;
    background-image: url("../../images/auth-one-bg.jpg");
    background-position: center center;
    background-repeat: no-repeat;
    background-size: cover;
    background-attachment: fixed;

    .bg-overlay{
        position: absolute;
        inset: 0;
        z-index: 0;
        background: linear-gradient(to bottom, rgba(0, 0, 0, 0.08), rgba(0, 0, 0, 0.22));
        opacity: 1;
        pointer-events: none;
    }
}

.shape{
    display: none;
}

// auth-pass-inputgroup — eye toggle centered on the input, clear of invalid icon
.auth-pass-inputgroup {
    &__control {
        position: relative;
    }

    &__toggle {
        position: absolute;
        top: 50%;
        right: 0.7rem;
        transform: translateY(-50%);
        z-index: 5;
        display: inline-flex;
        align-items: center;
        justify-content: center;
        width: 1.75rem;
        height: 1.75rem;
        padding: 0;
        margin: 0;
        border: 0;
        background: transparent;
        color: #64748b;
        line-height: 1;
        cursor: pointer;
        box-shadow: none;

        i {
            font-size: 1rem;
            line-height: 1;
        }

        &:hover,
        &:focus {
            color: #1e88e5;
            outline: none;
            box-shadow: none;
        }
    }

    .form-control,
    .auth-login-input {
        padding-right: 2.75rem !important;
    }

    .form-control.is-invalid,
    .auth-login-input.is-invalid {
        padding-right: 4.5rem !important;
        background-position: right 0.75rem center !important;
    }

    &__control:has(.is-invalid) .auth-pass-inputgroup__toggle {
        right: 2.5rem;
    }

    // Fallback where :has() is unsupported — sibling selector keeps the eye
    // clear of the Bootstrap invalid icon for both password fields.
    &__control .form-control.is-invalid ~ .auth-pass-inputgroup__toggle,
    &__control .auth-login-input.is-invalid ~ .auth-pass-inputgroup__toggle {
        right: 2.5rem;
    }

    // Show eye-off glyph when input type is text (legacy Register markup)
    input[type="text"] + .btn .ri-eye-fill,
    input[type="text"] + .auth-pass-inputgroup__toggle .ri-eye-fill {
        &:before {
            content: "\ecb6";
        }
    }
}

.particles-js-canvas-el{
    position: relative;
}

// Doctor registration wizard
.auth-register-card {
    border-radius: 18px;
    box-shadow: 0 18px 48px rgba(15, 23, 42, 0.12);
    overflow: hidden;
    border: 0;
    animation: authLoginCardIn 0.45s ease;

    .auth-register-title {
        font-size: 1.25rem !important;
        font-weight: 700;
        line-height: 1.3;
        color: #0f172a;
        letter-spacing: -0.02em;
    }

    .auth-register-lead {
        max-width: 34rem;
        margin-left: auto;
        margin-right: auto;
        font-size: 0.8125rem !important;
        font-weight: 500;
        line-height: 1.45;
        color: #64748b !important;
    }

    .auth-register-step__title {
        font-size: 0.8125rem;
        font-weight: 600;
        color: #334155;
        line-height: 1.25;
    }

    .auth-register-step.is-active .auth-register-step__title {
        color: #0f172a;
        font-weight: 700;
    }

    .auth-register-step__subtitle {
        font-size: 0.6875rem;
        font-weight: 500;
        color: #94a3b8;
        line-height: 1.3;
    }

    .auth-register-step__index {
        width: 1.75rem;
        height: 1.75rem;
        font-size: 0.75rem;
        font-weight: 600;
    }

    .auth-register-panel__title {
        font-size: 0.9375rem !important;
        font-weight: 700;
        color: #1e293b;
        margin-bottom: 0.85rem;
        line-height: 1.3;
    }

    .form-label {
        font-size: 0.75rem !important;
        font-weight: 600;
        color: #334155;
        margin-bottom: 0.35rem;
        line-height: 1.3;
    }

    .form-control,
    .form-select {
        min-height: 2.35rem;
        height: 2.35rem;
        font-size: 0.75rem !important;
        font-weight: 400;
        line-height: 1.35 !important;
        border-radius: 10px;
        border-color: #dbe3ef;
        background-color: #f8fbff;
    }

    textarea.form-control {
        height: auto;
        min-height: 4.5rem;
    }

    .form-control::placeholder,
    .form-select::placeholder {
        font-size: 0.75rem !important;
        font-weight: 400;
        color: #94a3b8;
    }

    .invalid-feedback,
    .form-text,
    .text-muted.small {
        font-size: 0.75rem !important;
        line-height: 1.35;
    }

    .auth-pass-inputgroup .form-control {
        padding-right: 2.75rem !important;
    }

    .auth-pass-inputgroup .form-control.is-invalid {
        padding-right: 4.5rem !important;
        background-position: right 0.75rem center !important;
    }

    .auth-pass-inputgroup__toggle {
        top: 50%;
        transform: translateY(-50%);
        width: 1.65rem;
        height: 1.65rem;

        i {
            font-size: 0.95rem;
        }
    }

    .btn {
        font-size: 0.8125rem;
        font-weight: 600;
    }

    .auth-register-success {
        h5 {
            font-size: 1.05rem !important;
            font-weight: 700;
        }

        p,
        .alert {
            font-size: 0.8125rem !important;
            line-height: 1.45;
        }
    }
}

.auth-register-title {
    color: #0f172a;
    font-weight: 700;
    letter-spacing: -0.02em;
}

.auth-register-lead {
    max-width: 34rem;
    margin-left: auto;
    margin-right: auto;
    font-size: 0.8125rem;
    line-height: 1.45;
}

.auth-register-steps {
    display: grid;
    grid-template-columns: 1fr auto 1fr auto 1fr;
    gap: 0.35rem;
    align-items: center;
}

.auth-register-step {
    display: flex;
    align-items: center;
    gap: 0.65rem;
    min-width: 0;
}

.auth-register-step__index {
    width: 1.75rem;
    height: 1.75rem;
    border-radius: 999px;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    font-size: 0.75rem;
    font-weight: 600;
    color: #64748b;
    background: #e2e8f0;
    flex-shrink: 0;
    transition: background-color 0.25s ease, color 0.25s ease, transform 0.25s ease;
}

.auth-register-step.is-active .auth-register-step__index,
.auth-register-step.is-done .auth-register-step__index {
    background: #1e88e5;
    color: #fff;
}

.auth-register-step.is-active .auth-register-step__index {
    transform: scale(1.05);
}

.auth-register-step__copy {
    display: flex;
    flex-direction: column;
    min-width: 0;
}

.auth-register-step__title {
    font-size: 0.8125rem;
    font-weight: 600;
    color: #334155;
    line-height: 1.25;
}

.auth-register-step.is-active .auth-register-step__title {
    color: #0f172a;
}

.auth-register-step__subtitle {
    font-size: 0.6875rem;
    color: #94a3b8;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}

.auth-register-step__connector {
    height: 2px;
    background: #e2e8f0;
    border-radius: 999px;
    transition: background-color 0.25s ease;
}

.auth-register-step__connector.is-done {
    background: #1e88e5;
}

.auth-register-panel {
    animation: authRegisterPanelIn 0.35s ease;
}

.auth-register-panel__title {
    font-weight: 700;
    color: #1e293b;
    margin-bottom: 0.85rem;
}

.auth-register-note {
    display: flex;
    align-items: flex-start;
    gap: 0.35rem;
    padding: 0.65rem 0.85rem;
    border-radius: 10px;
    background: #eff6ff;
    color: #1e40af;
    font-size: 0.75rem;
    font-weight: 500;
    line-height: 1.4;

    i {
        flex-shrink: 0;
        font-size: 0.95rem;
        line-height: 1.25;
        margin-top: 0.05rem;
    }
}

.auth-register-secondary-btn {
    border-radius: 10px;
    font-weight: 600;
}

.auth-register-success__icon {
    width: 4.5rem;
    height: 4.5rem;
    margin: 0 auto;
    border-radius: 999px;
    display: flex;
    align-items: center;
    justify-content: center;
    background: rgba(34, 197, 94, 0.12);
    color: #16a34a;
    font-size: 2.4rem;
    animation: authRegisterSuccessPop 0.45s ease;
}

// Shared login polish (aligned with Register)
.auth-login-card {
    .form-label {
        font-size: 0.75rem;
        font-weight: 600;
        color: #334155;
        margin-bottom: 0.45rem;
    }

    .auth-login-input {
        min-height: 46px;
        border-radius: 10px;
        border-color: #dbe3ef;
        background-color: #f8fbff;
        transition: border-color 0.2s ease, box-shadow 0.2s ease, background-color 0.2s ease;

        &:focus {
            background-color: #ffffff;
            border-color: #1e88e5;
            box-shadow: 0 0 0 0.2rem rgba(30, 136, 229, 0.15);
        }

        &.is-invalid {
            background-color: #fff;
        }
    }

    .auth-login-forgot {
        font-size: 0.75rem;
        font-weight: 500;
        line-height: 1.3;
        color: #64748b;
        text-decoration: none;

        &:hover {
            color: #1e88e5;
            text-decoration: underline;
        }
    }

    .auth-login-submit {
        font-weight: 700;
        letter-spacing: 0.01em;
        box-shadow: none !important;
        transition: background-color 0.2s ease, border-color 0.2s ease;

        &:hover:not(:disabled),
        &:focus:not(:disabled),
        &:active:not(:disabled) {
            transform: none;
            box-shadow: none !important;
        }
    }

    .auth-login-alert {
        border-radius: 12px;
        border: 0;
        font-size: 0.6875rem;
        line-height: 1.4;
    }

    // Sign In only: validation text stays smaller than the 0.75rem labels.
    .invalid-feedback {
        font-size: 0.6875rem !important;
        line-height: 1.35;
    }

    .form-check-input {
        width: 1.05rem;
        height: 1.05rem;
        margin-top: 0.15rem;
        border-radius: 0.3rem;

        &:checked {
            background-color: #1e88e5;
            border-color: #1e88e5;
        }
    }

    .form-check-label {
        color: #475569;
        font-size: 0.8125rem;
        font-weight: 500;
        line-height: 1.35;
    }

    .auth-register-note {
        font-size: 0.6875rem;
        font-weight: 500;
        line-height: 1.4;
        color: #1e40af;
        padding: 0.65rem 0.85rem;

        i {
            font-size: 0.95rem;
            line-height: 1.2;
            margin-top: 0.05rem;
        }
    }

    .mt-4.text-center > p {
        font-size: 0.8125rem;
        color: #64748b;

        .fw-semibold,
        a {
            font-size: inherit;
            font-weight: 600;
        }
    }
}

@keyframes authLoginCardIn {
    from {
        opacity: 0;
        transform: translateY(14px) scale(0.985);
    }
    to {
        opacity: 1;
        transform: translateY(0) scale(1);
    }
}

@keyframes authRegisterPanelIn {
    from {
        opacity: 0;
        transform: translateY(8px);
    }
    to {
        opacity: 1;
        transform: translateY(0);
    }
}

@keyframes authRegisterSuccessPop {
    from {
        opacity: 0;
        transform: scale(0.85);
    }
    to {
        opacity: 1;
        transform: scale(1);
    }
}

@media (max-width: 767.98px) {
    .auth-register-steps {
        grid-template-columns: 1fr;
        gap: 0.75rem;
    }

    .auth-register-step__connector {
        display: none;
    }

    .auth-register-step__subtitle {
        white-space: normal;
    }
}

// signin card title

.signin-other-title{
    position: relative;
    &:after{
        content: "";
        position: absolute;
        width: 100%;
        height: 1px;
        left: 0;
        right: 0;
        border-top: 1px dashed var(--#{$prefix}border-color);
        top: 10px;
    }

    .title{
        display: inline-block;
        position: relative;
        z-index: 9;
        background-color: var(--#{$prefix}secondary-bg);
        padding: 2px 16px;
    }
}

// Auth cover

.auth-bg-cover{
    background: $auth-bg-cover;

    > .bg-overlay{
        background-image: url("../../images/cover-pattern.png");
        background-position: center;
        background-size: cover;
        opacity: 1;
        background-color: transparent;
    }

    .footer{
        color: rgba($white, .5);
    }
}

//passowrd validations 
#password-contain {
    display: none;

    p {
        padding-left: 13px;

        &.valid {
            color: $success;

            &::before {
                position: relative;
                left: -8px;
                content: "✔";
            }
        }

        &.invalid {
            color: $danger;

            &::before {
                position: relative;
                left: -8px;
                content: "✖";
            }
        }
    }
}