//
// _modal.scss
//

.modal-title {
    font-weight: $font-weight-semibold;
    font-size: 13px;
    color: #000;
}

// Popup headings: semibold (600), compact — includes custom title markup outside .modal-title
.modal-header {
    padding: 0.7rem;
    font-weight: $font-weight-semibold;
    font-size: 13px;
    color: #000;
    background: #fff;
    border-bottom: none !important;
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 0.75rem;

    .modal-title,
    h1, h2, h3, h4, h5, h6,
    [class*="modal__title"]:not([class*="saved"]),
    [class$="__title-text"] {
        font-weight: $font-weight-semibold !important;
        font-size: 13px !important;
        color: #000 !important;
    }

    .btn,
    button:not(.btn-close) {
        font-weight: $font-weight-medium;
    }

    .btn-close {
        display: block !important;
        flex-shrink: 0;
        width: 1rem;
        height: 1rem;
        padding: 0.25rem;
        margin: 0 0 0 auto;
        opacity: 0.55;
        box-shadow: none;
        background-size: 1rem;
        filter: none;

        &:hover,
        &:focus {
            opacity: 0.85;
            box-shadow: none;
        }
    }
}

.offcanvas-header {
    .btn-close {
        display: block !important;
        flex-shrink: 0;
        width: 1rem;
        height: 1rem;
        padding: 0.25rem;
        margin: 0;
        opacity: 0.55;
        box-shadow: none;
        background-size: 1rem;
        filter: none;

        &:hover,
        &:focus {
            opacity: 0.85;
            box-shadow: none;
        }
    }
}

.offcanvas-header .offcanvas-title {
    font-weight: $font-weight-semibold !important;
    font-size: 13px !important;
    color: #000 !important;
}

.modal-body {
    padding: 0.7rem;
}

.offcanvas-header {
    padding: 0.5rem;
}

.offcanvas-body {
    padding: 0.5rem;
}

// Modal / offcanvas footers — base template soft buttons with icon spacing
$modal-footer-btn-height: calc(0.8rem * 1.5 + #{$input-padding-y} * 2 + #{$border-width * 2});

/* Compact soft action buttons — footer and in-body (e.g. Restore rows) */
.modal-action-btn.btn {
    box-shadow: none !important;
    display: inline-flex !important;
    align-items: center;
    justify-content: center;
    gap: 0.35rem;
    font-weight: 500;
    border-color: transparent !important;
    height: var(--app-form-field-height, #{$modal-footer-btn-height}) !important;
    min-height: var(--app-form-field-height, #{$modal-footer-btn-height}) !important;
    max-height: var(--app-form-field-height, #{$modal-footer-btn-height}) !important;
    font-size: 0.75rem !important;
    line-height: 1 !important;
    padding-top: 0 !important;
    padding-bottom: 0 !important;
    padding-left: 0.625rem !important;
    padding-right: 0.625rem !important;
    border-radius: $input-border-radius !important;
    white-space: nowrap;

    i[class^="ri-"],
    i[class*=" ri-"],
    .ri {
        font-size: 0.875rem;
        line-height: 1;
        margin: 0 !important;
    }

    .spinner-border,
    .spinner-border-sm {
        width: 0.85rem;
        height: 0.85rem;
        border-width: 0.12em;
        margin: 0 !important;
    }
}

.modal-footer,
.offcanvas-footer {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    justify-content: flex-end;
    gap: 0.5rem;
    padding: 0.5rem;
    border-top: 1px solid var(--#{$prefix}border-color);

    .btn:not(.btn-close),
    .modal-action-btn {
        box-shadow: none !important;
        display: inline-flex;
        align-items: center;
        justify-content: center;
        gap: 0.35rem;
        font-weight: 500;
        border-color: transparent !important;
        height: var(--app-form-field-height, #{$modal-footer-btn-height});
        min-height: var(--app-form-field-height, #{$modal-footer-btn-height});
        max-height: var(--app-form-field-height, #{$modal-footer-btn-height});
        font-size: 0.8rem;
        line-height: $input-line-height;
        padding-top: $input-padding-y;
        padding-bottom: $input-padding-y;
        padding-left: 0.625rem;
        padding-right: 0.625rem;
        border-radius: $input-border-radius !important;
        white-space: nowrap;

        i[class^="ri-"],
        i[class*=" ri-"],
        .ri {
            font-size: 0.95em;
            line-height: 1;
        }

        .spinner-border,
        .spinner-border-sm {
            width: 0.85rem;
            height: 0.85rem;
            border-width: 0.15em;
            flex-shrink: 0;
        }
    }

    @each $state in map-keys($theme-colors) {
        .btn-#{$state}:not([class*="btn-soft"]):not([class*="btn-outline"]):not([class*="btn-ghost"]):not(.btn-link),
        .btn-outline-#{$state}:not([class*="btn-soft"]),
        [class*="btn-ghost-#{$state}"] {
            --#{$prefix}btn-color: var(--#{$prefix}#{$state});
            --#{$prefix}btn-bg: var(--#{$prefix}#{$state}-bg-subtle);
            --#{$prefix}btn-border-color: transparent;
            --#{$prefix}btn-hover-bg: var(--#{$prefix}#{$state});
            --#{$prefix}btn-hover-border-color: transparent;
            --#{$prefix}btn-hover-color: #{$white};
            --#{$prefix}btn-active-bg: var(--#{$prefix}#{$state});
            --#{$prefix}btn-active-border-color: transparent;
            --#{$prefix}btn-active-color: #{$white};
            --#{$prefix}btn-focus-shadow-rgb: var(--#{$prefix}#{$state}-rgb);
        }
    }

    .btn-light:not([class*="btn-soft"]) {
        --#{$prefix}btn-color: var(--#{$prefix}secondary);
        --#{$prefix}btn-bg: var(--#{$prefix}secondary-bg-subtle);
        --#{$prefix}btn-border-color: transparent;
        --#{$prefix}btn-hover-bg: var(--#{$prefix}secondary);
        --#{$prefix}btn-hover-border-color: transparent;
        --#{$prefix}btn-hover-color: #{$white};
    }
}

.modal {
	&.fadeInRight {
		.modal-dialog {
			opacity: 0;
			transform: translateX(20%);
			transition: all .3s ease-in-out;
		}

		&.show {
			.modal-dialog {
				opacity: 1;
				transform: translateX(0);
			}
		}
	}

	&.fadeInLeft {
		.modal-dialog {
			animation: fadeInLeft 0.3s ease-in-out;
			transform: translate(-50%, 0);
		}

		&.show {
			.modal-dialog {
				transform: none;
			}
		}
	}

	&.fadeInUp {
		.modal-dialog {
			animation: fadeInUp 0.3s ease-in-out;
			transform: translate(0, 30%);
		}

		&.show {
			.modal-dialog {
				transform: none;
			}
		}
	}

	&.flip {
		perspective: 1300px;

		.modal-dialog {
			opacity: 0;
			transform: rotateY(-70deg);
			transition: all .3s;
		}

		&.show {
			.modal-dialog {
				opacity: 1;
				transform: rotateY(0deg);
			}
		}
	}

	&.zoomIn {
		.modal-dialog {
			opacity: 0;
			transform: scale(.7);
			transition: all .3s ease;
		}

		&.show {
			.modal-dialog {
				opacity: 1;
				transform: scale(1)
			}
		}
	}
}


.modal-dialog-right {
	margin-right: $modal-dialog-margin-y-sm-up;
}

// modal-dialog-bottom
.modal-dialog-bottom {
	display: flex;
	align-items: flex-end;
	min-height: calc(100% - #{$modal-dialog-margin-y-sm-up});

	@media (min-width: 576px) {
		min-height: calc(100% - #{$modal-dialog-margin-y-sm-up* 2 });
	}
}

.modal-dialog-bottom-right {
	display: flex;
	align-items: flex-end;
	min-height: calc(100% - #{$modal-dialog-margin-y-sm-up});
	margin-right: $modal-dialog-margin-y-sm-up;

	@media (min-width: 576px) {
		min-height: calc(100% - #{$modal-dialog-margin-y-sm-up*2 });
	}
}

@keyframes fadeInLeft {
	0% {
		opacity: 0;
		transform: translate3d(-30%, 0, 0);
	}

	to {
		opacity: 1;
		transform: translateZ(0);
	}
}


@keyframes fadeInUp {
	0% {
		opacity: 0;
		transform: translate3d(0, 30%, 0);
	}

	to {
		opacity: 1;
		transform: translateZ(0);
	}
}

@keyframes zoomIn {
	0% {
		opacity: 0;
		transform: scale3d(.3, .3, .3);
	}

	50% {
		opacity: 1
	}
}

