// Matches .form-control — compact field type for app-wide density
$app-form-field-font-size: 0.6875rem; // ~11px
$app-form-field-height: 1.75rem; // 28px — shared height for search + all admin inputs
$app-form-field-padding-y: 0.22rem;
// Match react-select / Bootstrap $input-padding-x so text inset matches dropdowns
$app-form-field-padding-x: 0.9rem;
// Actual rendered topbar height (.navbar-header override); differs from base template $header-height (70px)
$app-topbar-height: 60px;
// Match compacted horizontal menu-link padding (0.45rem y) + label/icon line
$app-horizontal-nav-height: 2.05rem;

:root {
  --app-form-field-font-size: #{$app-form-field-font-size};
  --app-form-field-height: #{$app-form-field-height};
  --app-form-field-padding-y: #{$app-form-field-padding-y};
  --app-form-field-padding-x: #{$app-form-field-padding-x};
  --app-topbar-height: #{$app-topbar-height};
  --app-modal-padding: 0.5rem;
  --app-modal-header-padding: 0.7rem;
  --app-modal-body-padding: 0.7rem;
  --app-icon-size: 1.0625rem; // ~17px default icons
  --app-icon-size-sm: 0.9375rem; // ~15px
  --app-icon-size-lg: 1.25rem; // ~20px

  /* Compact scrollbars app-wide */
  --app-scrollbar-size: 3px;
  --app-scrollbar-rail-size: 4px;
  --app-scrollbar-track: #e6eff5;
  --app-scrollbar-thumb: #045c8b;
  --app-scrollbar-thumb-hover: #034a70;
}

// ---------------------------------------------------------------------------
// App-wide compact typography + icons (sizes only — colors unchanged)
// ---------------------------------------------------------------------------
body {
  font-size: $font-size-base !important;
}

.navbar-header {
  .user-name-text {
    font-size: 0.75rem !important;
  }

  .user-name-sub-text {
    font-size: 0.625rem !important;
  }

  .header-item,
  .btn-topbar,
  .btn-icon {
    i,
    [class^="ri-"],
    [class*=" ri-"],
    [class^="mdi-"],
    [class*=" mdi-"],
    [class^="bx"],
    [class*=" bx"] {
      font-size: var(--app-icon-size) !important;
    }
  }
}

.navbar-menu,
.topnav {
  .navbar-nav {
    > .nav-item > .nav-link,
    > li > .nav-link {
      font-size: 0.6875rem !important;
      line-height: 1.25 !important;
      align-items: center !important;

      i,
      .nav-icon,
      [class^="ri-"],
      [class*=" ri-"],
      [class^="mdi-"],
      [class*=" mdi-"],
      [class^="bx"],
      [class*=" bx"] {
        font-size: var(--app-icon-size-sm) !important;
        line-height: 1 !important;
      }
    }

    .nav-sm .nav-link,
    .menu-dropdown .nav-link {
      font-size: 0.625rem !important;
    }
  }
}

.table,
.table th,
.table td,
.patient-list-modal__table th,
.patient-list-modal__table td {
  font-size: 0.6875rem !important;
}

// Doctor popup modals: match admin list table density (padding + type)
.modal.patient-list-modal,
.modal-dialog.patient-list-modal,
.patient-list-modal.modal {
  .patient-list-modal__table {
    thead th,
    tbody td {
      padding: 0.55rem 0.75rem !important;
      vertical-align: middle !important;
      line-height: 1.25 !important;
      font-size: 0.6875rem !important;
    }
  }

  .patient-list-modal__footer-text {
    font-size: 0.6875rem !important;
    line-height: 1.3 !important;
  }

  .patient-list-modal__footer {
    .pagination {
      gap: 0.35rem;
      --#{$prefix}pagination-color: #495057;
      --#{$prefix}pagination-hover-color: #25a0e2;
      --#{$prefix}pagination-focus-color: #25a0e2;
      --#{$prefix}pagination-active-color: #ffffff;
      --#{$prefix}pagination-active-bg: #25a0e2;
      --#{$prefix}pagination-active-border-color: #25a0e2;

      .page-item .page-link {
        width: 1.5rem;
        height: 1.5rem;
        min-width: 1.5rem;
        padding: 0 !important;
        display: inline-flex !important;
        align-items: center;
        justify-content: center;
        border-radius: 0.25rem !important;
        line-height: 1 !important;
        font-size: 0.75rem !important;
        font-weight: 400;
        border: 1px solid #cfe9ff !important;
        color: #495057 !important;
        background-color: #ffffff !important;
        box-shadow: none !important;
      }

      .page-item.active .page-link {
        background-color: #25a0e2 !important;
        border-color: #25a0e2 !important;
        color: #ffffff !important;
        box-shadow: none !important;
      }

      .page-item:not(.active):not(.disabled) .page-link:hover {
        background-color: #e8f5ff !important;
        border-color: #cfe9ff !important;
        color: #25a0e2 !important;
      }

      .page-item.disabled .page-link {
        opacity: 0.45;
        pointer-events: none;
      }
    }
  }

  .patient-list-modal__title-text {
    font-size: 0.75rem !important;
  }

  .patient-list-modal__meta,
  .patient-list-modal__status,
  .patient-list-modal__name-text {
    font-size: 0.6875rem !important;
  }

  // Catch remaining large body copy in doctor popup shells
  .modal-body p,
  .modal-body .text-muted,
  .modal-body .form-label,
  .modal-body label {
    font-size: 0.6875rem !important;
    line-height: 1.35 !important;
  }

  .modal-body .form-control,
  .modal-body .form-select {
    font-size: var(--app-form-field-font-size, 0.6875rem) !important;
  }
}

