// App-wide compact native scrollbars (overflow areas, textareas, modals, panels)
html {
  scrollbar-width: thin;
  scrollbar-color: var(--app-scrollbar-thumb) var(--app-scrollbar-track);
}

html * {
  scrollbar-width: thin;
  scrollbar-color: var(--app-scrollbar-thumb) var(--app-scrollbar-track);
}

html *::-webkit-scrollbar {
  width: var(--app-scrollbar-size) !important;
  height: var(--app-scrollbar-size) !important;
  -webkit-appearance: none;
  appearance: none;
}

html *::-webkit-scrollbar-track {
  background: var(--app-scrollbar-track);
  border-radius: 2px;
}

html *::-webkit-scrollbar-thumb {
  background: var(--app-scrollbar-thumb);
  border-radius: 2px;
}

html *::-webkit-scrollbar-thumb:hover {
  background: var(--app-scrollbar-thumb-hover);
}

html *::-webkit-scrollbar-button,
html *::-webkit-scrollbar-button:single-button,
html *::-webkit-scrollbar-button:vertical:start:decrement,
html *::-webkit-scrollbar-button:vertical:end:increment,
html *::-webkit-scrollbar-button:horizontal:start:decrement,
html *::-webkit-scrollbar-button:horizontal:end:increment {
  display: none !important;
  width: 0 !important;
  height: 0 !important;
  -webkit-appearance: none;
  appearance: none;
}

html *::-webkit-scrollbar-corner {
  background: transparent;
}

// Perfect Scrollbar (react-perfect-scrollbar)
.ps__rail-y,
.ps__rail-x {
  background: transparent !important;
  opacity: 1 !important;
}

.ps__rail-y {
  width: var(--app-scrollbar-rail-size) !important;
}

.ps__rail-x {
  height: var(--app-scrollbar-rail-size) !important;
}

.ps__thumb-y,
.ps__thumb-x {
  background-color: var(--app-scrollbar-thumb) !important;
  border-radius: 2px !important;
}

.ps__thumb-y {
  width: var(--app-scrollbar-size) !important;
  right: 0 !important;
}

.ps__thumb-x {
  height: var(--app-scrollbar-size) !important;
  bottom: 0 !important;
}

.ps__thumb-y:hover,
.ps__thumb-x:hover {
  background-color: var(--app-scrollbar-thumb-hover) !important;
}

// Explicit utility (Patient Board, tooltips, etc.)
.custom-scrollbar {
  scrollbar-width: thin;
  scrollbar-color: var(--app-scrollbar-thumb) var(--app-scrollbar-track);

  &::-webkit-scrollbar {
    width: var(--app-scrollbar-size) !important;
    height: var(--app-scrollbar-size) !important;
    -webkit-appearance: none;
    appearance: none;
  }

  &::-webkit-scrollbar-track {
    background: var(--app-scrollbar-track);
    border-radius: 2px;
  }

  &::-webkit-scrollbar-thumb {
    background: var(--app-scrollbar-thumb);
    border-radius: 2px;
  }

  &::-webkit-scrollbar-thumb:hover {
    background: var(--app-scrollbar-thumb-hover);
  }

  &::-webkit-scrollbar-button,
  &::-webkit-scrollbar-button:single-button,
  &::-webkit-scrollbar-button:vertical:start:decrement,
  &::-webkit-scrollbar-button:vertical:end:increment,
  &::-webkit-scrollbar-button:horizontal:start:decrement,
  &::-webkit-scrollbar-button:horizontal:end:increment {
    display: none !important;
    width: 0 !important;
    height: 0 !important;
    -webkit-appearance: none;
    appearance: none;
  }
}

