// Ghost-style action buttons (same tokens as .btn-ghost-*): tables, grids, square icon buttons, compact row actions
@mixin btn-ghost-variant-vars($state) {
  --#{$prefix}btn-color: var(--#{$prefix}#{$state});
  --#{$prefix}btn-bg: transparent;
  --#{$prefix}btn-border-color: transparent;
  --#{$prefix}btn-hover-color: var(--#{$prefix}#{$state});
  --#{$prefix}btn-hover-bg: var(--#{$prefix}#{$state}-bg-subtle);
  --#{$prefix}btn-hover-border-color: transparent;
  --#{$prefix}btn-focus-shadow-rgb: var(--#{$prefix}#{$state}-rgb);
  --#{$prefix}btn-active-color: var(--#{$prefix}#{$state});
  --#{$prefix}btn-active-bg: var(--#{$prefix}#{$state}-bg-subtle);
  --#{$prefix}btn-active-border-color: transparent;
  box-shadow: none !important;
}

@each $state in map-keys($theme-colors) {

  :is(.table, table) .btn-#{$state},
  :is(.table, table) .btn-soft-#{$state},
  :is(.table, table) .btn-outline-#{$state},
  .gridjs-wrapper .gridjs-td .btn-#{$state},
  .gridjs-wrapper .gridjs-td .btn-soft-#{$state},
  .gridjs-wrapper .gridjs-td .btn-outline-#{$state},
  table.dataTable .btn-#{$state},
  table.dataTable .btn-soft-#{$state},
  table.dataTable .btn-outline-#{$state},
  .btn.btn-icon.btn-#{$state},
  .btn.btn-icon.btn-soft-#{$state},
  .btn.btn-icon.btn-outline-#{$state},
  .btn.btn-sm.remove-item-btn.btn-#{$state},
  .btn.btn-sm.remove-item-btn.btn-soft-#{$state},
  .btn.btn-sm.remove-item-btn.btn-outline-#{$state},
  .btn.btn-sm.edit-item-btn.btn-#{$state},
  .btn.btn-sm.edit-item-btn.btn-soft-#{$state},
  .btn.btn-sm.edit-item-btn.btn-outline-#{$state},
  // Patient Board: compact soft/solid/outline .btn-sm (no btn-icon / edit-remove classes)
  .patient-board-page .btn.btn-sm.btn-#{$state},
  .patient-board-page .btn.btn-sm.btn-soft-#{$state},
  .patient-board-page .btn.btn-sm.btn-outline-#{$state} {
    @include btn-ghost-variant-vars($state);
  }
}

