// Tab selection: minimal theme blue + thin underline (app-wide)
$minimal-tab-active: #25a0e2;
$minimal-tab-indicator-height: 2px;

html:not([data-bs-theme="dark"]) {
  // base template nav-tabs-custom (underline grows on active)
  .nav-tabs-custom .nav-item .nav-link {
    &::after {
      background: $minimal-tab-active !important;
      height: $minimal-tab-indicator-height !important;
      border-radius: 0 !important;
    }

    &.active {
      color: $minimal-tab-active !important;
    }

    &:hover:not(.active) {
      color: $minimal-tab-active !important;
    }
  }

  // Bootstrap nav-tabs
  .nav-tabs .nav-link {
    border-bottom-width: $minimal-tab-indicator-height;

    &.active,
    &.active:hover,
    &.active:focus {
      color: $minimal-tab-active !important;
      border-bottom-color: $minimal-tab-active !important;
    }
  }

  // Theme-colored tab variants (nav-success, nav-primary, etc.)
  @each $state in map-keys($theme-colors) {
    .nav-#{$state}.nav-tabs-custom .nav-link {
      &.active {
        color: $minimal-tab-active !important;
        background-color: transparent !important;

        &::after {
          background-color: $minimal-tab-active !important;
          height: $minimal-tab-indicator-height !important;
        }
      }
    }

    .nav-#{$state}.nav-tabs .nav-link.active {
      color: $minimal-tab-active !important;
      border-bottom-color: $minimal-tab-active !important;
    }
  }

  .nav-border-top .nav-link.active {
    color: $minimal-tab-active !important;
    border-top-color: $minimal-tab-active !important;
    border-top-width: $minimal-tab-indicator-height !important;
  }

  .nav-custom-outline.nav .nav-link.active {
    color: $minimal-tab-active !important;
    border-color: $minimal-tab-active !important;
    border-bottom-width: $minimal-tab-indicator-height !important;
  }
}

